-- Generated by inua from ~/.config/inua/config.toml; changes
-- here are overwritten. Use inua's settings window, or edit config.toml and
-- run `inua config apply`.

local hl = _G.hl
if not hl then return end

-- Allow session lock restore for inua-shell
pcall(function() hl.config({ misc = { allow_session_lock_restore = true } }) end)

-- Window rules for inua light apps
pcall(function()
    hl.window_rule({
        match = { class = "^(io\\.github\\.lyricat\\.Inua\\..+)$" },
        float = true,
        center = true,
    })
end)

-- While inua's settings window records a shortcut, no other is active.
pcall(function()
    hl.define_submap("inua-record", function()
        hl.bind("SUPER + CTRL + ALT + Escape", hl.dsp.submap("reset"))
    end)
end)
